statement.tex:
\begin{enumerate}
  \item 3次関数 $f(x)$ が $\displaystyle\lim_{x\to1}\frac{f(x)}{x-1}=2,\ \lim_{x\to-1}\frac{f(x)}{x+1}=6$ を満たし，$x^3$ の係数が2であるとき，$f(x)$ を求めよ．
  \item 微分可能な関数 $f(x)$ について $\displaystyle\lim_{h\to0}\frac{f(a+2h)-f(a-h)}{h}$ を $f'(a)$ で表せ．
\end{enumerate}

\begin{enumerate}
  \item $f(x)=x^3+ax^2+bx+c$ が $x=-1$ で極大，$x=3$ で極小値0をとるとき，$a,b,c$ と極大値を求めよ．
  \item $f(x)=x^3-3ax^2+4$ の極大値と極小値の差が4となるような実数 $a$ を求めよ．
\end{enumerate}

整式 $f(x)$ がすべての $x$ について $f(x)f'(x)=2x^3-3x^2+x$ を満たす．
\begin{enumerate}
  \item $f(x)$ は2次式であることを示せ．
  \item $f(x)$ をすべて求めよ．
\end{enumerate}

$f(x)=x^3-3x$ の $t\leqq x\leqq t+1$ における最大値を $g(t)$ とする．
\begin{enumerate}
  \item $t\geqq-2$ の範囲で $g(t)$ を $t$ で表せ．
  \item $t\geqq-1$ の範囲で $g(t)$ の最小値を求めよ．
\end{enumerate}

$x$ の方程式 $x^3-3x-a=0$ について，
\begin{enumerate}
  \item 実数解の個数を $a$ の値によって分類せよ．
  \item 異なる3つの実数解をもつとき，最大の解 $\gamma$ の取り得る値の範囲を求めよ．
\end{enumerate}

実数 $x,y,z$ が $x+y+z=6,\ xy+yz+zx=9$ を満たす．
\begin{enumerate}
  \item $xyz$ の取り得る値の範囲を求めよ．
  \item $x$ の取り得る値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 整式 $f(x)$ が $(x-a)^2$ で割り切れるための必要十分条件は $f(a)=f'(a)=0$ であることを示せ．
  \item $x^5+ax+b$ が $(x-1)^2$ で割り切れるような $a,b$ を求めよ．
  \item $x^{10}$ を $(x-1)^2$ で割った余りを求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x+1$ とする．
\begin{enumerate}
  \item $y=f(x)$ のグラフは点 $(2,3)$ に関して対称であることを示せ．
  \item $a>0$ とする．$0\leqq x\leqq a$ における $f(x)$ の最大値を $a$ で表せ．
\end{enumerate}

曲線 $C:y=x^3$ 上の点 P$(t,t^3)$（$t\neq0$）における接線が，再び $C$ と交わる点を Q とする．
\begin{enumerate}
  \item Q の座標を求めよ．
  \item P における接線と Q における接線は決して直交しないことを示せ．
  \item 2本の接線のなす角を $\theta$（$0^\circ<\theta<90^\circ$）とするとき，$\tan\theta$ の最大値を求めよ．
\end{enumerate}

$f(x)=x^4-4x^3+2x^2+5x$ とする．
\begin{enumerate}
  \item 曲線 $y=f(x)$ と異なる2点で接する直線の方程式を求めよ．
  \item その2つの接点の $x$ 座標を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0<a<2$ とする．$S(a)=\displaystyle\int_0^2|x^2-ax|\,dx$ を $a$ で表し，その最小値を求めよ．
  \item $x^2-x-1=0$ の2解を $\alpha<\beta$ とするとき，$\displaystyle\int_\alpha^\beta(x^2-x-1)\,dx$ を求めよ．
\end{enumerate}

$f(x)=x^3+ax^2+bx+c$ とする．
\begin{enumerate}
  \item $\displaystyle\int_{-1}^1\{f(x)\}^2dx=\int_{-1}^1(x^3+bx)^2dx+\int_{-1}^1(ax^2+c)^2dx$ を示せ．
  \item $\displaystyle\int_{-1}^1\{f(x)\}^2dx$ を最小にする $a,b,c$ と，その最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての3次以下の整式 $f(x)$ に対して $\displaystyle\int_{-1}^1f(x)\,dx=pf(-1)+qf(0)+pf(1)$ が成り立つような定数 $p,q$ を求めよ．
  \item (1) の等式は $f(x)=x^4$ に対しては成り立たないことを示し，左辺と右辺の差を求めよ．
\end{enumerate}

$f(x)=\displaystyle\int_{-1}^1(x-t)^2(t+1)\,dt$ とする．
\begin{enumerate}
  \item $f(x)$ を $x$ の整式で表せ．
  \item $f(x)$ の最小値と，そのときの $x$ を求めよ．
\end{enumerate}

$a\geqq0$ とし，$S(a)=\displaystyle\int_0^1|x^2-a^2|\,dx$ とする．
\begin{enumerate}
  \item $S(a)$ を $a$ で表せ．
  \item $S(a)$ の最小値と，そのときの $a$ を求めよ．
\end{enumerate}

$F(x)=\displaystyle\int_0^x|t^2-1|\,dt\ (0\leqq x\leqq2)$ とする．
\begin{enumerate}
  \item $F(x)$ を $x$ の式で表せ．
  \item 方程式 $F(x)=x$ を $0<x\leqq2$ の範囲で解け．
  \item 方程式 $F(x)=1$ は $1<x<2$ にただ1つの解をもち，それは $x^3-3x+1=0$ を満たすことを示せ．
\end{enumerate}

整式 $f(x)$ が $\displaystyle\int_0^x(x-t)f(t)\,dt+f(x)=\frac{x^4}{12}+\frac{x^3}{3}+x^2+2x$ を満たす．
\begin{enumerate}
  \item $f(x)$ の次数を求めよ．
  \item $f(x)$ を求めよ．
\end{enumerate}

放物線 $y=x^2$ と点 $(1,2)$ を通る直線 $l$（傾き $m$）が2点 P，Q で交わる．
\begin{enumerate}
  \item 放物線と $l$ で囲まれた部分の面積を $m$ で表し，その最小値を求めよ．
  \item P，Q における放物線の接線が直交するとき，その面積を求めよ．
\end{enumerate}

点 A$(1,-2)$ から放物線 $y=x^2$ に2本の接線を引き，接点を P，Q とする．
\begin{enumerate}
  \item 2本の接線と放物線で囲まれた部分の面積 $S$ を求めよ．
  \item $\triangle APQ$ の面積 $T$ を求め，$S:T$ を求めよ．
\end{enumerate}

2つの放物線 $C_1:y=x^2$，$C_2:y=x^2-4x+8$ がある．
\begin{enumerate}
  \item $C_1,\ C_2$ の共通接線 $l$ の方程式を求めよ．
  \item $C_1$，$C_2$，$l$ で囲まれた部分の面積を求めよ．
\end{enumerate}

$C_1:y=x^2$，$C_2:y=2x^2$，$l:y=mx\ (m>0)$ とする．
\begin{enumerate}
  \item $C_1$ と $l$ で囲まれた部分の面積を $S_1$，$C_2$ と $l$ で囲まれた部分の面積を $S_2$ とする．$S_1:S_2$ は $m$ によらず一定であることを示せ．
  \item $C_1$，$C_2$，$l$ で囲まれた部分（$x>0$）の面積が1となる $m$ を求めよ．
\end{enumerate}

$0<a<b$ とし，曲線 $y=x(x-a)(x-b)$ と $x$ 軸で囲まれた2つの部分の面積が等しいとする．
\begin{enumerate}
  \item $b$ を $a$ で表せ．
  \item $a=1$ のとき，その面積を求めよ．
\end{enumerate}

曲線 $C:y=x^3-3x$ 上の点 P$(t,t^3-3t)\ (t>0)$ における接線を $l$ とし，$l$ と $C$ で囲まれた部分の面積を $S(t)$ とする．
\begin{enumerate}
  \item $S(t)$ を $t$ で表せ．（$-3x$ の項は結果に影響しないことに注意）
  \item $S(t)=108$ となる $t$ を求めよ．
\end{enumerate}

曲線 $y=x^3$ と放物線 $y=x^2+ax+b$ が点 $(1,1)$ で接している．
\begin{enumerate}
  \item $a,b$ を求めよ．
  \item 2曲線で囲まれた部分の面積を求めよ．
\end{enumerate}

$0<k<2$ とする．曲線 $y=|x^2-2x|$ と直線 $y=kx$ で囲まれた2つの部分の面積の和を $S(k)$ とする．
\begin{enumerate}
  \item $S(k)$ を $k$ で表せ．
  \item $S(k)$ を最小にする $k$ を求めよ．
\end{enumerate}

$a$ を実数とし，$f(x)=x^3+3ax^2+3(a+2)x+1$ とする．
\begin{enumerate}
  \item $f(x)$ が極値をもつような $a$ の範囲を求めよ．
  \item $f(x)$ が $x=p$ で極大，$x=q$ で極小となるとき，2点 P$(p,f(p))$，Q$(q,f(q))$ を結ぶ直線の傾き $m$ を $a$ で表せ．
  \item 直線 PQ が原点を通るような $a$ の値を求めよ．
\end{enumerate}

縦 $x$，横 $y$，高さ $z$ の和が $9$，表面積が $48$ である直方体を考える．
\begin{enumerate}
  \item $y+z$ と $yz$ を $x$ の式で表せ．
  \item このような直方体が存在するための $x$ の範囲を求めよ．
  \item 体積の最大値と最小値を求め，そのときの3辺の長さを答えよ．
\end{enumerate}

$a$ を実数とし，$f(x)=x^3-3ax+2a$ とする．
\begin{enumerate}
  \item $0\leqq x\leqq2$ において常に $f(x)\geqq0$ となるような $a$ の範囲を求めよ．
  \item $0<a\leqq4$ のとき，$0\leqq x\leqq2$ における $f(x)$ の最小値を $m(a)$ とする．$m(a)$ の最大値と，そのときの $a$ を求めよ．
\end{enumerate}

$f_1(x)=x^2-6x+11$，$f_2(x)=x^2+2x+1$ に対して，$F(x)=\min\{f_1(x),\ f_2(x)\}$ と定める．
\begin{enumerate}
  \item $y=F(x)$ のグラフをかけ．
  \item 曲線 $y=F(x)$ と異なる2点で接する直線 $l$ を求めよ．
  \item 曲線 $y=F(x)$ と $l$ で囲まれた部分の面積を求めよ．
\end{enumerate}

3次曲線 $C:y=x^3-3x$ とその上の点 P$(2,2)$ について考える．点 P での $C$ の接線が $C$ と交わる P 以外の点を Q とする．また，R は P と異なる $C$ 上の点で，直線 PR は R で $C$ に接する．
\begin{enumerate}
  \item 点 Q，R の座標を求めよ．
  \item 直線 PR と曲線 $C$ で囲まれた部分の面積を求めよ．
  \item 直線 PQ と曲線 $C$ で囲まれた部分の面積を求めよ．
\end{enumerate}

$y=x^2$ のグラフを $\Gamma$ とする．$b<a^2$ を満たす点 P$(a,b)$ から $\Gamma$ へ接線を2本引き，接点を A，B とする．$\Gamma$ と2つの線分 PA，PB で囲まれた図形の面積を $S$ とする．
\begin{enumerate}
  \item $S$ を $a,b$ で表せ．
  \item $S=\frac23$ となるような点 P の軌跡を求めよ．
  \item P が直線 $y=x-2$ 上を動くとき，$S$ の最小値を求めよ．
\end{enumerate}

$f(x)=x^3$，$g(x)=ax^2+bx+c$ とし，$y=f(x)$ と $y=g(x)$ のグラフが点 $(1,1)$ で共通の接線をもつとする．
\begin{enumerate}
  \item $b,c$ を $a$ で表し，$f(x)-g(x)$ を因数分解せよ．
  \item $f(x)-g(x)$ の $-1\leqq x\leqq1$ における最小値を $a$ で表せ．
\end{enumerate}

関数 $f(x)=\displaystyle\int_0^1|t^2-3xt+2x^2|\,dt$ について，
\begin{enumerate}
  \item $f\bigl(\frac12\bigr)$，$f(1)$ の値を求めよ．
  \item $\frac12\leqq x\leqq1$ のとき，$f(x)$ を求めよ．
  \item $\displaystyle\int_{-1}^2f(x)\,dx$ を求めよ．
\end{enumerate}

放物線 $y=x^2$ を $C_1$，$y$ 軸上の点 $(0,a)\ (a>0)$ を中心とする半径 $r$ の円を $C_2$ とする．
\begin{enumerate}
  \item $a>\frac12$ のとき，$r$ を0から大きくしていくと $C_2$ が $C_1$ とはじめて共有点をもつときの共有点の座標を求めよ．
  \item (1) の共有点における $C_2$ の接線が $\bigl(0,-\frac14\bigr)$ を通るとき，$C_2$ の方程式を求めよ．
  \item (2) の円 $C_2$ と放物線 $C_1$ で囲まれた図形のうち，円の下側にある部分の面積を求めよ．
\end{enumerate}

$f(x)=x^4-4x^2+4x$，$g(x)=x^4-4x^2-4x$ とする．
\begin{enumerate}
  \item $f(x)$ の極値をすべて求めよ．
  \item $f(x)$ の最小値と，そのときの $x$ を求めよ．
  \item $g(x)$ の最小値と，そのときの $x$ を求めよ．
\end{enumerate}

実数の定数 $a\ (a\neq0,\ a\neq-2)$，$b$，$c$ に対し，$f(x)=ax^3+bx^2-12x+c$ を考える．$f(x)$ が $x=a$ および $x=-2$ で極値をもつとき，
\begin{enumerate}
  \item $a,b$ の値をすべて求めよ．
  \item 極小値が0となるような $c$ の値を，(1) のそれぞれの場合について求めよ．
  \item 極大値と極小値の差を，(1) のそれぞれの場合について求めよ．
\end{enumerate}

$k$ を実数とする．3次関数 $y=x^3-3kx^2+3x$ が極大値と極小値をもち，極大値から極小値を引いた値が $\sqrt2\,|k|^3$ になるとする．
\begin{enumerate}
  \item 極値をもつための $k$ の条件を求めよ．
  \item 極大値から極小値を引いた値を $k$ で表せ．
  \item $k$ の値を求めよ．
\end{enumerate}

$t$ を正の実数とし，$f(x)=x^3-3x^2-3(t^2-1)x+2t^3+3t^2-1$ とおく．
\begin{enumerate}
  \item $2t^3+3t^2-1$ を因数分解せよ．
  \item $f(x)$ が極小値0をもつことを示せ．
  \item $0\leqq x\leqq2$ における $f(x)$ の最小値 $m$ と最大値 $M$ を $t$ の式で表せ．
\end{enumerate}

$a$ を実数とし，$f(x)=x^3-3ax$ とする．区間 $-1\leqq x\leqq2$ における $|f(x)|$ の最大値を $M$ とする．
\begin{enumerate}
  \item $f(2)$，$f(1)$ を $a$ で表し，すべての $a$ について $M\geqq2$ であることを示せ．
  \item $M$ の最小値と，そのときの $a$ の値を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x$ とする．
\begin{enumerate}
  \item $f(x)$ の極値を求めよ．
  \item 方程式 $f(x)=k$ が異なる3つの実数解をもつ $k$ の範囲を求めよ．
  \item (2) のとき3つの解を $\alpha<\beta<\gamma$ とする．$2<\beta<\dfrac52$ となるとき，$\alpha$ の範囲を求めよ．
\end{enumerate}

曲線 $C:\ y=x(x-t)^2$（$t>0$ は定数）がある．
\begin{enumerate}
  \item $C$ 上の点 $(p,\ p(p-t)^2)$ における接線が点 A$(a,0)$ を通る条件を $p$ の方程式で表せ．
  \item A から $C$ に異なる3本の接線が引けるような $a$ の範囲を $t$ で表せ．
  \item (2) の場合，3本の接線のうち2本が垂直に交わるとき，$a$ を $t$ で表せ．
\end{enumerate}

曲線 $C:\ y=x^4-4x^3+2x^2+x$ がある．直線 $l$ は $C$ に異なる2点で接している．$\displaystyle\int(x-\alpha)^2(x-\beta)^2dx$ の計算は $x-\alpha=s$ と置換してよい．
\begin{enumerate}
  \item $l$ の方程式と接点の $x$ 座標を求めよ．
  \item $C$ と $l$ で囲まれる図形の面積を求めよ．
  \item 実数 $a$ に対して，点 $(0,a)$ を通る $C$ の接線の本数を求めよ．
\end{enumerate}

$a$ を定数とし，$f(x)=-x^3+3x$，$g(x)=x^2-4x+a$ を考える．
\begin{enumerate}
  \item $x\geqq0$ における $g(x)$ の最小値を $a$ で表せ．
  \item $x\geqq0$ を満たすすべての $x$ に対して $f(x)\leqq g(x)$ となる $a$ の範囲を求めよ．
  \item $b_1\geqq0,\ b_2\geqq0$ を満たすすべての $b_1,b_2$ に対して $f(b_1)\leqq g(b_2)$ となる $a$ の範囲を求めよ．
\end{enumerate}

縦 $x$，横 $y$，高さ $z$ の直方体の対角線の長さは $\sqrt{14}$，全表面積は22である．
\begin{enumerate}
  \item $x+y+z$ と $xy+yz+zx$ を求めよ．
  \item 体積 $V$ の最大値と最小値を求めよ．
  \item 体積が最大のとき，最も長い辺の長さを求めよ．
\end{enumerate}

正の実数 $a$ に対して $S=\displaystyle\int_0^2|x^3-ax|\,dx$ とおく．
\begin{enumerate}
  \item $S$ を $a$ で表せ．
  \item $a$ が正の実数全体を動くとき，$S$ の最小値と最小値を与える $a$ を求めよ．
\end{enumerate}

整式 $f(x)$ は，等式 $4\displaystyle\int_0^xtf'(t)\,dt=3(x+1)f(x)-3$ を満たすものとする．
\begin{enumerate}
  \item $f(0)$ を求めよ．
  \item $f(x)$ の次数を求めよ．
  \item $f(x)$ を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の2点 A$(a,a^2)$，B$(b,b^2)$（$a<b$）における接線の交点を P とする．線分 AB の中点を M，直線 MP と放物線の交点を Q とし，Q における接線が AP，BP と交わる点をそれぞれ R，T とする．
\begin{enumerate}
  \item 線分 AB と放物線で囲まれる部分の面積 $S_1$，2本の接線と放物線で囲まれる部分の面積 $S_2$ を求めよ．
  \item $\triangle$AQB の面積 $S_3$ と $\triangle$PRT の面積 $S_4$ を求めよ．
  \item $S_1:S_2:S_3:S_4$ を求めよ．
\end{enumerate}

2つの放物線 $C_1:\ y=x^2-4x+1$，$C_2:\ y=x^2+2x-5$ に共通な接線を $l$ とし，$C_1$，$C_2$ との接点をそれぞれ P$_1$，P$_2$ とする．
\begin{enumerate}
  \item $C_1$ と $C_2$ の交点の $x$ 座標を求めよ．
  \item P$_1$，P$_2$ の $x$ 座標と $l$ の方程式を求めよ．
  \item $C_1$，$C_2$ と $l$ で囲まれた図形の面積を求めよ．
\end{enumerate}

放物線 $C:\ y=x^2+1$ と，点 $(1,4)$ を通り傾きが $m$ である直線 $l$ について，
\begin{enumerate}
  \item $C$ と $l$ が異なる2点で交わることを示せ．
  \item $C$ と $l$ で囲まれた部分の面積 $S$ を $m$ の式で表せ．
  \item $S$ が最小となるときの直線 $l$ の方程式と $S$ の最小値を求めよ．
\end{enumerate}

放物線 $y=x^2$ を $C_1$，放物線 $y=-3x^2-2$ を $C_2$ とする．$a$ を $a\neq0$，$a^2\neq\dfrac32$ を満たす定数とし，$C_1$ 上の点 A$(a,a^2)$ における $C_1$ の接線と，$C_2$ 上の点 B における $C_2$ の接線は平行であるとする．2点 A，B を通る直線を $l$ とし，$l$ と $C_1$ の A 以外の交点を P，$l$ と $C_2$ の B 以外の交点を Q とする．
\begin{enumerate}
  \item B の座標と直線 $l$ の方程式を $a$ で表せ．
  \item P と Q の $x$ 座標を $a$ で表せ．
  \item $l$ と $C_1$ で囲まれた部分の面積を $S_1$，$l$ と $C_2$ で囲まれた部分の面積を $S_2$ とするとき，$\dfrac{S_2}{S_1}$ を求めよ．
\end{enumerate}

関数 $f(x)=-x^2+4x+4|x-1|-4$ について，
\begin{enumerate}
  \item $y=f(x)$ を絶対値を含まない式で表し，グラフの概形を述べよ．
  \item 曲線 $y=f(x)$ と直線 $y=ax$ が4点を共有するような $a$ の範囲を求めよ．
  \item 曲線 $y=f(x)$ と直線 $y=2x$ で囲まれた部分の面積の総和を求めよ．
\end{enumerate}

曲線 $C:\ y=|x(x-2)|$ と直線 $l:\ y=mx$ について，
\begin{enumerate}
  \item $C$ と $l$ が3つの共有点をもつ $m$ の範囲を求めよ．
  \item (1) のとき，$C$ と $l$ とで囲まれる2つの部分の面積の和 $S(m)$ を求めよ．
  \item $S(m)$ が最小となる $m$ の値を求めよ．
\end{enumerate}

$p$ を実数とする．関数 $y=x^3+px^2+4x$ のグラフ $C_1$ と関数 $y=2x^2$ のグラフ $C_2$ は，$x>0$ の範囲に共有点を2個もつとする．
\begin{enumerate}
  \item このような $p$ の範囲を求めよ．
  \item $x>0$ にある共有点の $x$ 座標を $\alpha,\beta$（$\alpha<\beta$）とし，$0\leqq x\leqq\alpha$ と $\alpha\leqq x\leqq\beta$ で $C_1$ と $C_2$ が囲む部分の面積をそれぞれ $S_1,S_2$ とする．$S_1=S_2$ となる $p$ と，そのときの $S_1$ を求めよ．
\end{enumerate}

$f(x)=x^3-3x-2$ とし，$\alpha<-1$ とする．曲線 $C:\ y=f(x)$ 上の点 P$(\alpha,f(\alpha))$ における接線と $x$ 軸の交点を Q とする．Q を通る $C$ の接線のうち，傾きが最小のものを $l$ とする．
\begin{enumerate}
  \item Q の $x$ 座標を求めよ．また，$l$ と $C$ の接点の $x$ 座標を $\alpha$ で表せ．
  \item $\alpha=-2$ とする．$l$ の方程式と，$l$ と $C$ で囲まれた部分の面積を求めよ．
\end{enumerate}

座標平面上に曲線 $C_1:\ y=x^3-4x$ と，$C_1$ を $x$ 軸方向に $t$（$t>0$）だけ平行移動させた曲線 $C_2$ がある．$C_1$ と $C_2$ は2つの共有点をもつという．
\begin{enumerate}
  \item $t$ の範囲を求めよ．
  \item $C_1$ と $C_2$ で囲まれる図形の面積 $S$ を $t$ で表せ．
  \item $S$ の最大値とそのときの $t$ の値を求めよ．
\end{enumerate}

$f(x)=x^4+2x^3-3x^2+x+2$ とする．曲線 $y=f(x)$ の接線のうち，異なる2点で接するものを $l$ とする．
\begin{enumerate}
  \item $l:\ y=mx+n$ と接点の1つ $(\alpha,f(\alpha))$ について，$P(x)=f(x)-mx-n$ は $(x-\alpha)^2$ で割り切れることを示せ．
  \item $l$ の方程式と2つの接点の $x$ 座標を求めよ．
  \item $y=f(x)$ と $l$ で囲まれた部分の面積 $S$ を求めよ．
\end{enumerate}

$xy$ 平面上に点 A$(s,t)$ と曲線 $C:\ y=x^3-3x$ がある．$C$ 上に $x$ 座標が $\alpha,\beta,\gamma$（$\alpha<\beta<\gamma$）である3点があり，それぞれの点における接線が A を通るとき，
\begin{enumerate}
  \item A の存在範囲を不等式で表せ．
  \item $\alpha,\beta,\gamma$ が等差数列になるとき，$s,t$ が満たす条件を求めよ．
\end{enumerate}

放物線 $C_1:\ y=\dfrac12x^2$ 上の点 A$\left(1,\frac12\right)$ における $C_1$ の接線を $l$ とする．円 $C_2$ は点 A で直線 $l$ に接し，点 H で $x$ 軸に接している．ただし H の $x$ 座標は1より大きい．
\begin{enumerate}
  \item $l$ の方程式と，A を通り $l$ に垂直な直線 $m$ の方程式を求めよ．
  \item 円 $C_2$ の中心 B の座標と半径を求めよ．また $\angle$ABH を求めよ．
  \item 放物線 $C_1$（原点 O から A まで），円 $C_2$ の劣弧 AH，および $x$ 軸で囲まれた部分の面積 $S$ を求めよ．
\end{enumerate}

2つの曲線 $C_1:\ y=x^2-2$ と $C_2:\ x=y^2-2$ を考える．
\begin{enumerate}
  \item $C_1,C_2$ の共有点をすべて求めよ．
  \item 2つの領域 $y\geqq x^2-2$ と $x\geqq y^2-2$ の共通部分 $W$ の面積 $S$ を求めよ．
\end{enumerate}

関数 $f(x)=x^3-4x$ について考える．
\begin{enumerate}
  \item 関数 $y=|f(x)|$ の極大値を求めよ．
  \item $m>0$ とする．直線 $l:\ y=mx$ と曲線 $C:\ y=|f(x)|$ が相異なる3つの共有点をもつような $m$ の範囲と，共有点の $x$ 座標をすべて求めよ．
  \item (2) のとき，直線 $l$ と曲線 $C$ で囲まれた2つの部分の面積の和 $S$ を $m$ の式で表し，$S$ を最小にする $m$ の値を求めよ．
\end{enumerate}

半径1の球がある．球に内接するように直円柱（底面の半径 $r$，高さ $h$）をおき，さらに直円柱の上の底面を底面とし，頂点が球面に接する直円錐を1つおく．直円柱と直円錐をあわせてできる立体の体積を $V$ とする．
\begin{enumerate}
  \item $r$ と $h$ の関係を求めよ．
  \item $V$ を $h$ で表せ．
  \item $V$ の最大値と，そのときの $h$ を求めよ．
\end{enumerate}

$xy$ 平面上に曲線 $C:y=\dfrac12x^2$ がある．$C$ 上の点 $\mathrm P\left(t,\frac12t^2\right)$（$t>0$）における接線を，Pを中心として反時計回りに $90^\circ$ 回転して得られる直線を $l$ とする．
\begin{enumerate}
  \item $l$ の方程式を求めよ．
  \item $C$ と $l$ で囲まれる部分の面積 $S(t)$ を求めよ．
  \item $S(t)$ を最小にする $t$ の値と最小値を求めよ．
\end{enumerate}

平面上に，原点O，点A$(2,0)$，点B$(0,1)$ を頂点とする$\triangle$OABがある．辺OA上の動点 $\mathrm P(p,0)$ と，辺OB上の動点 $\mathrm Q(0,q)$ は，$\triangle$OPQ の面積が $\triangle$OAB の面積の $\frac14$ になるように動く．
\begin{enumerate}
  \item $p$ のとりうる値の範囲を求めよ．
  \item $0\leqq x\leqq2$ を固定したとき，線分PQ上の点で $x$ 座標が $x$ であるものの $y$ 座標の最大値と最小値を求めよ．
  \item 線分PQが通過する部分の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $f(x)=x^2+px+q$ について $f(1)+f(-1)-2f(0)=2$ を示し，$-1\leqq x\leqq1$ における $|f(x)|$ の最大値 $M$ は $M\geqq\frac12$ をみたすことを示せ．また等号が成り立つ $p,q$ を求めよ．
  \item $g(x)=x^3+px^2+qx+r$ について $g(1)-2g\left(\frac12\right)+2g\left(-\frac12\right)-g(-1)$ の値を求め，$-1\leqq x\leqq1$ における $|g(x)|$ の最大値は $\frac14$ 以上であることを示せ．
  \item (2) で最大値がちょうど $\frac14$ となる $g(x)$ を1つ求め，$\cos3\theta$ との関係を述べよ．
\end{enumerate}

$xy$ 平面上の点Pを通る直線で，放物線 $y=x^2$ とで囲まれた部分の面積が $\frac43$ となるものを考える．
\begin{enumerate}
  \item そのような直線が存在する点Pの範囲を求めよ．
  \item そのような直線がちょうど1本存在する点Pの範囲を求めよ．
  \item 傾きが0以上のそのような直線が存在する点Pの範囲を求めよ．
\end{enumerate}

3次曲線 $y=x^3-kx$ 上の点P（$x$ 座標 $t\neq0$）における接線が曲線と再び交わる点をQ，Qにおける接線が曲線と再び交わる点をRとする．
\begin{enumerate}
  \item Q，Rの $x$ 座標を $t$ で表せ．
  \item Pにおける接線とRにおける接線が直交するような $t$ が存在する $k$ の範囲を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の点 $\mathrm P(x,x^2)$ を中心とし，この放物線とP以外の点Qで接する円を考える．
\begin{enumerate}
  \item そのような円が描けるPの $x$ 座標の範囲を求めよ．
  \item そのような円の半径の最小値と，そのときのPの座標を求めよ．
\end{enumerate}

曲線 $C:y=x^3-3x^2$ について，点 $(a,b)$ から $C$ に引ける接線の本数を考える．
\begin{enumerate}
  \item 接点の $x$ 座標を $t$ とするとき，$t$ がみたす3次方程式を求めよ．
  \item 接線がちょうど3本引ける点 $(a,b)$ の範囲を求めよ．
  \item 接線がちょうど2本引ける点 $(a,b)$ の範囲を求め，それらの点はどのような図形上にあるか答えよ．
\end{enumerate}

放物線 $C:y=x^2$ 上の2点 $\mathrm P(p,p^2)$，$\mathrm Q(q,q^2)$（$p\neq q$，$pq\neq0$）における $C$ の法線を $l_1,l_2$ とし，その交点をRとする．
\begin{enumerate}
  \item Rの座標を $p+q$，$pq$ で表せ．
  \item $l_1\perp l_2$ のとき，Rの軌跡を求めよ．
  \item $pq=\frac14$ をみたしながら P，Q が動くとき，Rの軌跡を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 4次関数 $y=f(x)$ のグラフが直線 $x=\alpha$ に関して対称であることは，$f'(\alpha)=f'''(\alpha)=0$ と同値であることを示せ．
  \item $f(x)=x^4-4x^3+qx^2+rx$ のグラフが $y$ 軸に平行な対称軸をもつための $q,r$ の条件を求めよ．
  \item (2) の条件のもとで，$f(x)$ が極大値と極小値をもち，その差が4であるとき，$f(x)$ を求めよ．
\end{enumerate}

3次関数 $f(x)=x^3+ax^2+bx+c$ は $x=\alpha$ で極大値，$x=\beta$ で極小値をとる．2点 $(\alpha,f(\alpha))$，$(\beta,f(\beta))$ は直線 $y=-3x+4$ 上にあり，2点 $(\alpha,f(\beta))$，$(\beta,f(\alpha))$ は直線 $y=3x+m$ 上にある．
\begin{enumerate}
  \item $\alpha+\beta$ を $m$ で表せ．また，2本目の直線の傾きが3以外では条件をみたす3次関数が存在しないことを示せ．
  \item $m=-2$ のとき，$a,b,c$ の値を求めよ．
\end{enumerate}

2つの放物線 $y=x^2$ ……①，$y=-x^2+ax+b$ ……② が，交点の1つPで接線が互いに直交している．
\begin{enumerate}
  \item ②は $a$ の値に無関係な一定の点Qを通ることを示し，Qの座標を求めよ．
  \item Pの $x$ 座標を $t$ とするとき，$a$ を $t$ で表し，$a$ のとり得る値の範囲を求めよ．
\end{enumerate}

4次関数 $y=f(x)$（最高次の係数 $a>0$）のグラフ上の2点 P$(-1,f(-1))$，Q$(1,f(1))$ における接線が一致している．
\begin{enumerate}
  \item $f(x)-L(x)=a(x-1)^2(x+1)^2$ を示せ（$L(x)$ は共通の接線）．
  \item 曲線 $y=f(x)$ の2つの変曲点 $\mathrm I_1,\mathrm I_2$ を結ぶ直線はPQに平行であることを示せ．
  \item 直線 $\mathrm I_1\mathrm I_2$ は曲線と $\mathrm I_1,\mathrm I_2$ 以外にさらに2点 R，S で交わる（R，$\mathrm I_1$，$\mathrm I_2$，S の順）．$\mathrm{RI_1}:\mathrm{I_1I_2}=1:\dfrac{1+\sqrt5}2$ を示せ．
\end{enumerate}

3次方程式 $f(x)=x^3-3x^2+a=0$ が相異なる3つの実数解 $\alpha<\beta<\gamma$ をもつ．
\begin{enumerate}
  \item $a$ のとり得る値の範囲と，$\alpha,\beta,\gamma$ の各存在範囲を求めよ．
  \item $|\alpha|<\beta$ であることを示せ．
  \item $|\alpha|+|\beta|+|\gamma|$ のとり得る値の範囲を求めよ．
\end{enumerate}

4次関数 $f(x)$ は $x=0$ と $x=4$ で極小値 $-2$ をとり，極大値は6である．
\begin{enumerate}
  \item $f(x)$ を求め，そのグラフが直線 $x=2$ に関して対称であることを示せ．
  \item 曲線 $y=f(x)$ と直線 $y=-2$ で囲まれた部分の面積を求めよ．
\end{enumerate}

$f(x)=x^4-4x^3+2x^2$ とする．
\begin{enumerate}
  \item 曲線 $y=f(x)$ と異なる2点で接する直線を求めよ．
  \item (1) の直線と曲線で囲まれた部分の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 放物線 $y=x^2$ 上の2点 A$(\alpha,\alpha^2)$，B$(\beta,\beta^2)$（$\alpha<\beta$）について，弧AB上の点Pで $\triangle\mathrm{ABP}$ の面積が最大となるものを求め，弦ABと放物線で囲まれる部分の面積が $\frac43\triangle\mathrm{ABP}$ であることを示せ．
  \item 曲線 $C:y=x^3-3x$ 上の点 $x=1$ における接線が $C$ と再び交わる点を $x=x_1$，そこでの接線が再び交わる点を $x=x_2$ とする．接線と $C$ で囲まれる2つの部分の面積 $S_1,S_2$ と比 $S_1:S_2$ を求めよ．
\end{enumerate}

2次関数 $f(x)=x^2+ax+b$ が $\displaystyle\int_0^1f(x)dx=0$，$\displaystyle\int_0^1xf(x)dx=0$ をみたすとする．
\begin{enumerate}
  \item $a,b$ を求め，$f(x)=0$ の2解がともに $0<x<1$ にあることを確かめよ．
  \item 一般に，連続関数 $h(x)$ が $\int_0^1h\,dx=\int_0^1xh\,dx=0$ をみたし，$0<x<1$ で $h(x)=0$ となる点が有限個ならば，$h$ は $0<x<1$ で少なくとも2回符号を変えることを示せ．
\end{enumerate}

\begin{enumerate}
  \item 2次関数 $y=f(x)$ のグラフが2点 $(p,1)$，$(q,1)$（$p<q$）を通るとき，$\displaystyle\int_p^qf(x)dx=(q-p)f(r)$ をみたす $r$ を $p,q$ で表せ．
  \item $m=\frac{p+q}2$ とする．3次以下の任意の整式 $f(x)$ に対して $\displaystyle\int_p^qf(x)dx=\frac{q-p}6\{f(p)+4f(m)+f(q)\}$ を示せ．
\end{enumerate}

$p>0$，$q$ は実数とする．放物線 $C_1:y=x^2$ と $C_2:y=(x-p)^2+q$ を考える．
\begin{enumerate}
  \item $C_1$，$C_2$ の共通接線をただ1本もつことを示し，その接点の $x$ 座標を求めよ．
  \item $C_1$，$C_2$ と共通接線で囲まれる部分の面積を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の異なる2点P，Qにおける接線の交点をR，線分PQの中点をMとする．
\begin{enumerate}
  \item 放物線と2接線で囲まれた部分の面積がつねに18となるように P，Q が動くとき，Rの軌跡を求めよ．
  \item 放物線と弦PQで囲まれた部分の面積がつねに36となるように P，Q が動くとき，Mの軌跡を求めよ．
  \item (1)(2) の条件は同値であることを確かめ，そのとき R と M を結ぶ線分の中点が放物線上にあることを示せ．
\end{enumerate}

曲線 $C_1:y=px^4+qx^2+1$ は点A$(1,0)$を通り，曲線 $C_2:y=a(x^2-1)$ と点Aにおいて共通の接線をもつ（$a>-1$，$a\neq0$）．
\begin{enumerate}
  \item $p,q$ を $a$ で表し，$C_1$ の式を因数分解せよ．
  \item $C_1$ と $x$ 軸で囲まれた部分のうち，$x$ 軸より上の部分の面積と下の部分の面積の和が等しくなるような $a$ をすべて求めよ．
\end{enumerate}

多項式 $f(x)$ が $f(x)=(x-1)f'(x)-\{f'(x)\}^2$，$f'(3)=1$ をみたす．
\begin{enumerate}
  \item $f(x)$ が3次以上にならない理由を述べよ．
  \item $f(x)$ をすべて求めよ．
\end{enumerate}

3次関数 $f(x)=x^3+ax^2+bx$ は極大値と極小値をもち，それらを区間 $0\leqq x\leqq2$ 内でとるものとする．
\begin{enumerate}
  \item この条件をみたす点 $(a,b)$ の存在範囲を図示せよ．
  \item (1) の範囲の面積を求めよ．
\end{enumerate}

$a$ は実数とする．傾きが $m$ である2つの直線が，曲線 $y=x^3-3x^2+ax$ とそれぞれ点 A，B で接している．
\begin{enumerate}
  \item 線分ABの中点 C は曲線上にあることを示せ．
  \item 直線ABの方程式が $y=2x-3$ であるとき，$a,m$ の値と A，B の $x$ 座標を求めよ．
\end{enumerate}

$a,b$ は実数として，$f(x)=x^4-4x^3+ax^2+bx$ とする．
\begin{enumerate}
  \item 曲線 $y=f(x)$ が異なる2点で共通の接線 $\ell$ をもつための $a$ の条件を求め，$\ell$ の方程式を $a,b$ で表せ．
  \item $f(x)$ が極大値をもつための必要十分条件を $a,b$ の不等式で表せ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ を考える．
\begin{enumerate}
  \item $-2<t<2$ のとき，3点 $(2,0)$，$\left(t,\sqrt{1-\frac{t^2}4}\right)$，$\left(t,-\sqrt{1-\frac{t^2}4}\right)$ を頂点とする三角形の面積を最大にする $t$ と最大値を求めよ．
  \item (1) の三角形を $x$ 軸のまわりに回転させてできる円錐の体積の最大値と，そのときの $t$ を求めよ．
\end{enumerate}

実数 $a,b$ に対し $f(x)=x^3-3ax+b$ とし，$0\leqq x\leqq2$ における $|f(x)|$ の最大値を $M$ とする．
\begin{enumerate}
  \item $\left(\sqrt3-1\right)f(0)-\sqrt3f\left(\frac2{\sqrt3}\right)+f(2)$ の値を求めよ．
  \item $M\geqq\dfrac{8\sqrt3}9$ を示せ．
  \item $M=\dfrac{8\sqrt3}9$ となる $a,b$ を求めよ．
\end{enumerate}

方程式 $|x^3-4x|=x+k$ ……① の実数解について考える（$k$ は実数の定数）．
\begin{enumerate}
  \item ① が異なるちょうど3個の実数解をもつような $k$ の値を2つ求めよ．
  \item (1) の小さい方の $k$ について，① の解を求めよ．
  \item ① の実数解の個数が最大となる $k$ の範囲と，そのときの個数を求めよ．
\end{enumerate}

3次関数 $f(x)=x^3+ax^2+b$ について，曲線 $y=f(x)$ 上の点 $(t,f(t))$ における接線を $\ell_t$ とする．
\begin{enumerate}
  \item $\ell_t$ が原点を通るような $t$ がただ1つに定まるための $a,b$ の条件を求めよ．
  \item そのような $t$ がちょうど2つあるための $a,b$ の条件を求めよ．
\end{enumerate}

3次関数 $y=x^3-3x$ のグラフを $C$ とし，$C$ と直線 $y=-3x$ ではさまれた部分（境界を除く）を $D$ とする．
\begin{enumerate}
  \item $D$ 内の点 P$(p,q)$ を通り $C$ に接する直線は3本あることを示せ．
  \item その3本の接線の傾きの和が0で，積が $\dfrac{135}4$ となるような点 P の座標を求めよ．
\end{enumerate}

$a,b$ は正の実数とする．放物線 $C_1:y=x^2-a$ と $C_2:y=-b(x-3)^2$ は，ともに点 P$(x_0,y_0)$ において直線 $\ell$ に接している．$S_1$ を直線 $x=0$ と $C_1$ と $\ell$ で囲まれた部分の面積，$S_2$ を直線 $x=3$ と $C_2$ と $\ell$ で囲まれた部分の面積とする．
\begin{enumerate}
  \item $a,x_0,y_0$ を $b$ で表せ．
  \item $S_1:S_2$ を $b$ で表せ．
\end{enumerate}

点 P から放物線 $y=x^2$ へ2本の接線が引けるとき，2つの接点を A，B とし，線分 PA，PB と放物線で囲まれる図形の面積を $S$ とする．
\begin{enumerate}
  \item A，B の $x$ 座標を $\alpha<\beta$ とするとき，$S=\dfrac{(\beta-\alpha)^3}{12}$ を示せ．
  \item PA$\perp$PB となるように P が動くとき，P の軌跡と $S$ の最小値を求めよ．
\end{enumerate}

定数 $a$（$a<1$），$b,c$ に対し，$f(x)=x^3-(a+2)x^2+(2a+b)x-a+c$ とする．曲線 $C:y=f(x)$ は点 A$(1,3)$ を通り，A において直線 $\ell:y=3x$ と接している．$C$ と $\ell$ の A 以外の共有点を B とする．
\begin{enumerate}
  \item $b,c$ の値を求め，B の座標を $a$ で表せ．
  \item $C$ と $\ell$ で囲まれた部分の面積 $S_1$ を $a$ で表せ．
  \item $x$ が $a<x<1$ の範囲を動くとき，3点 P$(x,f(x))$，A，B が作る三角形の面積の最大値を $S_2$ とする．$\dfrac{S_2}{S_1}$ の値を求めよ．
\end{enumerate}

曲線 $C:y=x(x+1)(x-2)^2$ と直線 $\ell:y=m(x+1)$ について答えよ．
\begin{enumerate}
  \item $m$ が実数全体を動くとき，$C$ と $\ell$ の共有点の個数を調べよ．
  \item $m>0$ で，$C$ と $\ell$ の共有点の個数が3であるとき，$m$ の値と共有点の $x$ 座標を求めよ．
  \item (2) のとき，$C$ と $\ell$ で囲まれた図形の面積を求めよ．
\end{enumerate}

$m$ は正の実数である．放物線 $C_1:y=x^2+m^2$ 上の点 P における $C_1$ の接線と放物線 $C_2:y=x^2$ の交点を A，B とし，$C_2$ 上の A と B の間の点 Q に対して，直線AQと $C_2$ で囲まれる領域の面積と，直線QBと $C_2$ で囲まれる領域の面積の和を $S$ とする．
\begin{enumerate}
  \item 直線ABと $C_2$ で囲まれる領域の面積は P のとり方によらないことを示し，その値を求めよ．
  \item Q が A と B の間を動くときの $S$ の最小値を求め，(1) の面積との比を答えよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $y=-x^4+4x^2$ のグラフと直線 $y=k$ が4点で交わる $k$ の範囲を求めよ．
  \item (1) のとき，4つの交点の $x$ 座標を $-\alpha,-\beta,\beta,\alpha$（$0<\beta<\alpha$）とする．$\dfrac{\alpha^3+\beta^3}{\alpha+\beta}$ と $\dfrac{\alpha^5+\beta^5}{\alpha+\beta}$ を $k$ で表せ．
  \item グラフと直線 $y=k$ で囲まれる3つの部分の面積が等しくなる $k$ を求めよ．
\end{enumerate}

実数 $t$ に対して2点 P$(t,t^2)$，Q$(t+1,(t+1)^2)$ を考える．
\begin{enumerate}
  \item 2点P，Qを通る直線 $\ell$ の方程式を求めよ．
  \item $a$ を定数とし，直線 $x=a$ と $\ell$ の交点の $y$ 座標を $f(t)$ とする．$t$ が $0\leqq t\leqq1$ を動くときの $f(t)$ の最大値を $a$ で表せ．
  \item $t$ が $0\leqq t\leqq1$ を動くとき，線分PQが通過してできる図形を図示し，その面積を求めよ．
\end{enumerate}

$f(x)=x^3-3x$ とし，曲線 $y=f(x)$ を $C$，点P$(a,f(a))$ における接線を $\ell$，法線を $n$ とする．
\begin{enumerate}
  \item $\ell$，$n$ の方程式を求めよ（$f'(a)=0$ の場合も含めて）．
  \item $\ell$ と $C$ の共有点でP以外のものの個数を求めよ．
  \item $|a|<1$ のとき，$n$ と $C$ の共有点がP以外にも存在することを示せ．また，そのような $a$ の範囲をすべて求めよ．
\end{enumerate}

3次関数 $f(x)=x^3-3ax-2b$ について答えよ．
\begin{enumerate}
  \item $a>0$ のとき，$f(x)$ の極大値と極小値を求めよ．
  \item 次を示せ．(ア) $b^2>a^3$ のとき $f(x)=0$ はただ1つの実数解をもつ．(イ) $b^2=a^3$，$a>0$ のとき異なる2つの実数解をもつ．(ウ) $b^2<a^3$ のとき異なる3つの実数解をもつ．
  \item $x^3-3x-2\cos\theta=0$ の3つの解を $\theta$ で表せ．
\end{enumerate}

整式 $f_0(x),f_1(x),\dots$ が，$f_n(0)\neq0$ のとき $f_{n+1}(x)=f_n'(x)$，$f_n(0)=0$ のとき $f_{n+1}(x)=\displaystyle\int_0^xf_n(t)dt+1$ をみたしている．
\begin{enumerate}
  \item $f_0(x)=(x-1)^2$ のとき，$f_4(x)$ を求めよ．
  \item $f_3(x)=0$ となるような $f_0(x)$ をすべて求めよ．
\end{enumerate}

2つの曲線 $y=x^3-3x$ ……①，$y=(x-a)^3-3(x-a)$ ……②（$a>0$）がある．
\begin{enumerate}
  \item ②が $x=x_1$ で極大，$x=x_2$ で極小となる点をA，Bとするとき，直線ABの方程式を求めよ．
  \item ①，②が異なる2点で交わるような $a$ の範囲を求め，交点の $x$ 座標を $\alpha<\beta$ として $\beta-\alpha$ を $a$ で表せ．
  \item ①，②で囲まれた部分の面積 $S$ を $a$ で表し，$S$ の最大値を求めよ．
\end{enumerate}

放物線 $C:y=4-x^2$ 上に2点 P$(p,4-p^2)$，Q$(q,4-q^2)$（$p<q$）をとる．
\begin{enumerate}
  \item 2つの線分OP，OQと $C$ で囲まれた部分の面積 $S$ を $p,q$ で表せ．
  \item $q=p+1$ のとき $S$ の最小値を求めよ．
  \item $pq=-1$ のとき $S$ の最小値を求めよ．
\end{enumerate}

$-1\leqq t\leqq1$ をみたす実数 $t$ に対して，直線 $l_t:\ y=3t^2x-2t^3$（曲線 $y=x^3$ の点 $(t,t^3)$ における接線）を考える．
\begin{enumerate}
  \item $k\geqq0$ とする．直線 $x=k$ 上で $l_t$ が通過する部分を求めよ．
  \item $l_t$ の通過領域は原点に関して対称であることを示し，通過領域を求めよ．
  \item 直線 $x=k$ 上の通過部分の長さ $L(k)$ を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x$ とし，$0\leqq a\leqq3$ に対して区間 $a\leqq x\leqq a+1$ における $f(x)$ の最大値を $M(a)$，最小値を $m(a)$ とする．
\begin{enumerate}
  \item $f(a+1)=f(a)$ をみたす $a$ を求めよ．
  \item $M(a)$ を求め，$M(a)$ の最小値を求めよ．
  \item $m(a)$ の最大値を求めよ．
\end{enumerate}

$a>0$ とし，$f(x)=x^3-3a^2x$（$-1\leqq x\leqq2$）の最大値を $M(a)$ とする．
\begin{enumerate}
  \item $M(a)$ の候補となる値を $a$ の関数として3つ挙げ，それぞれが候補となる $a$ の範囲を答えよ．
  \item $M(a)$ を求めよ．
  \item $M(a)$ の最小値と，そのときの $a$ を求めよ．
\end{enumerate}

solutions.tex:
$f'(x)=3(x-2)(x-2p)$．$f(0)=0$，$f(1)=9p-2$，$f(2p)=4p^2(3-p)$．
$0<p\leqq\frac12$：$x=2p\in(0,1]$ で極大．$\frac12<p<1$：$[0,1]$ で増加．
\begin{itemize}
  \item 最大値：\textbf{$0<p\leqq\frac12$ のとき $4p^2(3-p)$，$\frac12<p<1$ のとき $9p-2$}．
  \item 最小値：\textbf{$0<p\leqq\frac29$ のとき $9p-2$，$\frac29\leqq p<1$ のとき 0}．
\end{itemize}

statement.tex:
$f(x)=x^3+ax^2+bx+c$ とし，曲線 $C:y=f(x)$ を考える．
\begin{enumerate}
  \item $C$ が原点に関して点対称であるための $a,b,c$ の条件を求めよ．
  \item $f(x)=x^3-4x$ とする．原点を通る直線 $y=mx$ が $C$ と原点以外の2点 P，Q で交わるとき，原点は線分 PQ の中点であることを示せ．
  \item (2) で PQ$=2\sqrt{10}$ となる $m$ をすべて求めよ．
\end{enumerate}

曲線 $D:y=2x^3+6x^2-3x+1$ について答えよ．
\begin{enumerate}
  \item $y=2(x-p)^3+k(x-p)+q$ の形に変形し，$D$ がある点に関して点対称であることを示して，対称の中心を求めよ．
  \item $D$ を平行移動して原点対称な曲線にするときの移動量と，移動後の曲線の方程式を求めよ．
  \item $D$ 上の点 $(x_0,y_0)$ の対称点の座標を $x_0,y_0$ で表せ．
\end{enumerate}

曲線 $D:y=x^3-3x^2+4$ がある．
\begin{enumerate}
  \item 傾き1の直線 $y=x+n$ と $D$ で囲まれる部分が2つあり，その面積が等しいとき，$n$ の値を求め，そのときの面積を求めよ．
  \item 対称の中心を通る傾き $m$（$m>-3$）の直線と $D$ で囲まれる2つの部分の一方の面積を $S(m)$ とする．$S(m)$ を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x+1$ とし，曲線 $C:y=f(x)$ 上の点 $\mathrm A(\alpha,f(\alpha))$ における接線が $C$ と再び交わる点を $\mathrm B(\beta,f(\beta))$ とする（$\alpha\neq2$）．
\begin{enumerate}
  \item $\beta$ を $\alpha$ で表せ．
  \item A における接線と B における接線が平行になることはないことを示せ．
  \item B における接線が $C$ と再び交わる点の $x$ 座標が 14 となるような $\alpha$ を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x$ とし，$a>0$ に対して $0\leqq x\leqq a$ における $f(x)$ の最大値を $M(a)$ とする．
\begin{enumerate}
  \item $M(a)$ を求めよ．
  \item $M(a)=2a$ となる $a$ をすべて求めよ．
\end{enumerate}

曲線 $C:y=x^3-3x^2$ 上に $x$ 座標が $a_1=2$ の点 $\mathrm A_1$ をとる．$\mathrm A_n$ における接線が $C$ と再び交わる点を $\mathrm A_{n+1}$ とし，その $x$ 座標を $a_{n+1}$ とする．$\mathrm A_n$ における接線と $C$ で囲まれる部分の面積を $S_n$ とする．
\begin{enumerate}
  \item $a_n$ を $n$ で表せ．
  \item $S_1$ を求めよ．また $S_{n+1}=16S_n$ を示せ．
\end{enumerate}

$f(x)=\dfrac{x^3}3-x^2-3x+2$ とし，曲線 $y=f(x)$ 上の相異なる2点 $\mathrm P(x_1,f(x_1))$，$\mathrm Q(x_2,f(x_2))$ における接線が平行であるとする．
\begin{enumerate}
  \item $x_2$ を $x_1$ で表せ．
  \item 曲線を $x$ 軸方向に $a$，$y$ 軸方向に $b$ 平行移動すると原点対称になる．$a,b$ と移動後の方程式を求めよ．
  \item P における法線が Q を通るような $x_1$ をすべて求めよ．
\end{enumerate}

$C:y=x^3-x^2$，$D:y=x^2+5x-6$ とする．また $k,m$ を定数として $C':y=x^3+2x^2-4x+k$，$D':y=4x^2+x+m$ とする．
\begin{enumerate}
  \item $C$ と $D$ の交点の $x$ 座標を求め，$C$ と $D$ で囲まれる部分の面積の和を求めよ．
  \item $C'$ と $D'$ が $x=3$ で交わるとき，$C'$ と $D'$ の交点の $x$ 座標と，囲まれる部分の面積の和を求めよ．
\end{enumerate}

放物線 $C:y=2x^2-4x+3$ 上の点 P における接線 $l$ と放物線 $D:y=2x^2-4x+1$ が2点 A，B で交わる．
\begin{enumerate}
  \item $l$ と $D$ で囲まれる部分の面積は P によらず一定であることを示し，その値を求めよ．
  \item A，B の $x$ 座標の差は一定であることと，P の $x$ 座標は A，B の $x$ 座標の平均であることを示せ．
\end{enumerate}

放物線 $C:y=x^2$，$D:y=x^2-8x+18$ がある．
\begin{enumerate}
  \item $C$ と $D$ の共通接線 $l$ の方程式と，2つの接点の $x$ 座標を求めよ．
  \item $C$，$D$，$l$ で囲まれる部分の面積を求め，$C$ と $D$ の交点を通る $y$ 軸に平行な直線でちょうど2等分されることを確かめよ．
\end{enumerate}

点 A$(2,7)$ を通る傾き $m$ の直線 $l$ と放物線 $C:y=x^2-2x+3$ で囲まれる部分の面積を $S(m)$ とする．
\begin{enumerate}
  \item $S(m)$ を $m$ で表せ．
  \item $S(m)$ を最小にする $l$ の方程式と，最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=x^4+4x^3-4x^2-13x+14$ の複接線を求めよ．
  \item 曲線 $y=x^4+4x^3+kx^2$ が複接線をもつような $k$ の範囲を求め，そのときの複接線の方程式を $k$ で表せ．
\end{enumerate}

4次関数 $f(x)=x^4-2x^3-3x^2+4x+1$ について答えよ．
\begin{enumerate}
  \item $f(x)$ を $f'(x)$ で割った余りを求めよ．
  \item $y=f(x)$ のグラフ上の極値をとる3点を通り，軸が $y$ 軸に平行な放物線の方程式を求めよ．また，3点の $x$ 座標を求めて確かめよ．
\end{enumerate}

$a$ を実数とし，$f(x)=x^3+ax^2+(2a+3)x+1$ とする．
\begin{enumerate}
  \item $f(x)$ が極値をもつ $a$ の範囲を求めよ．
  \item 極値をとる2点を通る直線の方程式を $a$ で表せ．
  \item (2) の直線が原点を通るような $a$ の値と，そのときの直線の傾きを求めよ．
\end{enumerate}

連立不等式 $y\geqq0$，$x+y\leqq4$，$y-3x\leqq12$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ を図示せよ．
  \item $(x,y)$ が $D$ を動くとき，$4x-y$ の最大値と最小値を求めよ．
  \item $(x,y)$ が $D$ を動くとき，$y-x^2$ の最大値と最小値，およびそのときの $(x,y)$ を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+13x-7$ とする．
\begin{enumerate}
  \item $f(x)=(x-2)^3+a(x-2)+b$ をみたす定数 $a,b$ を求めよ．
  \item $\displaystyle\int_{-998}^{1002}f(x)\,dx$ を求めよ．
  \item $\displaystyle\sum_{k=-50}^{54}f(k)$ を求めよ．
\end{enumerate}

曲線 $C:y=x^3+ax^2+bx+c$ は $x$ 軸に接し，直線 $y=d$ との3つの交点の $x$ 座標は公差 $h\ (>0)$ の等差数列をなす．
\begin{enumerate}
  \item $C$ と $x$ 軸で囲まれた部分の面積 $S_1$ を $h$ で表せ．
  \item $C$ と直線 $y=d$ で囲まれた2つの部分の面積の和 $S_2$ を $h$ で表せ．
  \item $\dfrac{S_1}{S_2}$ は $h,a,b,c,d$ によらず一定であることを示し，その値を求めよ．
\end{enumerate}

$x=\alpha$ で極大値 $M$，$x=\beta$ で極小値 $m$ をとる3次関数 $f(x)$ を考える（$\alpha\neq\beta$，$m<M$）．
\begin{enumerate}
  \item $f(x)$ を $\alpha,\beta,M,m$ で表せ．
  \item $\displaystyle\int_\alpha^\beta f(x)\,dx$ を $\alpha,\beta,M,m$ で表せ．
  \item $f(x)=M$ をみたす $x$ のうち $\alpha$ 以外のものを求めよ．
\end{enumerate}

4次関数 $f(x)=x^4+ax^3+bx^2+cx+d$ が $x=\alpha,\gamma,\beta$（$\alpha<\gamma<\beta$）で極値をとるとする．
\begin{enumerate}
  \item $f(\beta)-f(\alpha)=\dfrac23(\beta-\alpha)^3\left(\gamma-\dfrac{\alpha+\beta}2\right)$ を示せ．
  \item $f(\alpha)<f(\beta)$ となるための条件を，$a$ と $\gamma$ を用いて表せ．
  \item $f(x)=x^4-\dfrac43x^3-12x^2$ の2つの極小値の大小を比べ，その差を求めよ．
\end{enumerate}

動点Pは初速度 $5$ m/秒，加速度 $2$ m/秒$^2$ で点Aから東に向かって進む．Pが出発して4秒後に，動点Qが点Aを出発して東に一定の速さ $v$ m/秒でPを追う．
\begin{enumerate}
  \item QがPに追い着くための $v$ の最小値と，そのとき追い着く時刻・地点を求めよ．
  \item $v=26$ のとき，QがPの前にいる時間帯と，その間のQとPの距離の最大値を求めよ．
\end{enumerate}

4次関数 $y=f(x)$（$x^4$ の係数は正）のグラフ $C_1$，2次関数 $y=g(x)$（$x^2$ の係数は負）のグラフ $C_2$，1次関数 $y=h(x)$ のグラフ $C_3$ があり，$C_1$ と $C_3$ は相異なる2点A，Bで接し，$C_2$ は A，B を通る．$C_1$ と $C_3$ で囲まれる図形の面積を $S_1$，$C_2$ と $C_3$ で囲まれる図形の面積を $S_2$ とする．
\begin{enumerate}
  \item $C_1$ と $C_2$ が A，B 以外に共有点をもたないとき，$\dfrac{S_2}{S_1}$ のとり得る値の範囲を求めよ．
  \item $C_1$ と $C_2$ の共有点がちょうど3個のとき，3つ目の共有点の $x$ 座標を A，B の $x$ 座標 $\alpha,\beta$ で表し，$C_1$ と $C_2$ で囲まれる図形の面積は $S_1$ の何倍か求めよ．
  \item $C_1$ と $C_2$ の共有点が4個のとき，$\dfrac{S_2}{S_1}$ のとり得る値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $g(x)=(x-2)^3-3(x-2)$ について，$0\leqq x\leqq4$ における $|g(x)|$ の最大値を求めよ．
  \item 実数 $a,b,c$ に対して $f(x)=x^3+ax^2+bx+c$ とする．$f(4)-2f(3)+2f(1)-f(0)$ の値を求めよ．
  \item $0\leqq x\leqq4$ における $|f(x)|$ の最大値 $M$ は2以上であることを示し，$M=2$ となる $(a,b,c)$ を求めよ．
\end{enumerate}

3次式 $f(x)=ax^3+bx^2+cx+d$（$a\neq0$）について，方程式 $f(x)=0$ は相異なる3つの正の解 $\alpha<\beta<\gamma$ をもつとする．
\begin{enumerate}
  \item $k>0$ のとき，方程式 $f(x)+kxf'(x)=0$ は相異なる3つの正の解をもち，それぞれ区間 $(0,\alpha)$，$(\alpha,\beta)$，$(\beta,\gamma)$ に1つずつあることを示せ．
  \item 方程式 $f(x)-\frac13xf'(x)=0$ は2次方程式であり，相異なる2つの正の解を区間 $(\alpha,\beta)$，$(\beta,\gamma)$ に1つずつもつことを示せ．
  \item $f(x)=(x-1)(x-2)(x-3)$ のとき，(2) の2解を求めよ．
\end{enumerate}

1つの頂点から出る3辺の長さが $x,y,z$ の直方体で，$x+y+z=9$，全表面積が48であるとする．
\begin{enumerate}
  \item この直方体の対角線の長さを求めよ．
  \item 体積 $V$ のとり得る値の範囲を求めよ．
  \item 最も長い辺の長さのとり得る値の範囲を求めよ．
\end{enumerate}

$k$ を実数とし，$f(x)=x^3-3x+k$ とおく．$f(x)=0$ が相異なる3つの実数解 $\alpha<\beta<\gamma$ をもつとする．
\begin{enumerate}
  \item $k$ の範囲と，$\alpha,\beta,\gamma$ の各存在範囲を求めよ．
  \item $f'(\alpha)+f'(\beta)+f'(\gamma)$ は $k$ によらない定数であることを示し，その値を求めよ．また，$\dfrac1{f'(\alpha)}+\dfrac1{f'(\beta)}+\dfrac1{f'(\gamma)}=0$ を示せ．
  \item $f'(\alpha)f'(\beta)f'(\gamma)$ を $k$ で表し，そのとり得る値の範囲を求めよ．
\end{enumerate}

$f(x)=x^3-6x^2+9x$ とし，$C:y=f(x)$ とする．
\begin{enumerate}
  \item $C$ は点 $(2,2)$ に関して対称であることを示せ．
  \item $C$ の傾き $m$（$m>-3$）の2本の接線の接点の $x$ 座標を $\alpha<\beta$，それぞれの接線が $C$ と再び交わる点の $x$ 座標を $\varepsilon$，$\delta$ とする．$\delta,\ \alpha,\ 2,\ \beta,\ \varepsilon$ はこの順に等間隔に並ぶことを示せ．
  \item $\varepsilon-\delta=6$ となる $m$ を求め，そのときの2本の接線の方程式を求めよ．
\end{enumerate}

3次関数 $f(x)=x^3-3ax^2+3bx$ は極大値と極小値をもち，その差が32である．さらに，極大点と極小点を結ぶ線分の中点が直線 $y=-x$ 上にあるという．
\begin{enumerate}
  \item $f(x)=(x-a)(x^2-2ax+b)+2(b-a^2)x+ab$ を示し，極大値と極小値の差を $a,b$ で表せ．
  \item 定数 $a,b$ の値の組をすべて求めよ．
\end{enumerate}

$a$ を定数とし，$f(x)=x^3-3ax^2+a$ とする．$x\leqq2$ の範囲での $f(x)$ の最大値を $M(a)$ とする．
\begin{enumerate}
  \item $M(a)$ を $a$ で表せ．
  \item $M(a)=30$ となる $a$ をすべて求めよ．
  \item $M(a)$ の最小値と，そのときの $a$ を求めよ．
\end{enumerate}

$f(x)=x^3-3x$ とする．
\begin{enumerate}
  \item 実数 $a$ に対して，$f(x)=a$ をみたす実数 $x$ の個数を求めよ．
  \item $f(f(x))=x$ をみたす実数 $x$ をすべて求めよ．
  \item $f(f(f(x)))=1$ をみたす実数 $x$ の個数を求めよ．
\end{enumerate}

関数 $y=x(x-1)(x-2)$ のグラフを $C$，原点Oを通る傾き $t$ の直線を $l$ とし，$C$ と $l$ がO以外にも共有点をもつとする．$C$ と $l$ の共有点をO，P，Qとし（接する場合は2点が一致し，$t=2$ のときはPがOに一致するとする），$|\overrightarrow{\mathrm{OP}}|\cdot|\overrightarrow{\mathrm{OQ}}|=g(t)$ とおく．
\begin{enumerate}
  \item $t$ のとり得る値の範囲を求め，$g(t)$ を $t$ で表せ．
  \item $g(t)$ の増減を調べ，極値を求めよ．
\end{enumerate}

底面の半径が1，高さが3の直円錐を考える．
\begin{enumerate}
  \item 直円錐と軸が一致し，直円錐に内接する直円柱の体積の最大値を求めよ．
  \item 直円錐と軸が一致する2つの直円柱A，Bを考える．Aは下底が直円錐の底面上にあり上底の周が円錐面上にある．Bは下底がAの上底面上にあり上底の周が円錐面上にある．AとBの体積の和の最大値と，そのときのA，Bの底面の半径を求めよ．
\end{enumerate}

円 $C$ は放物線 $P:y=x^2$ と点 $\mathrm A\left(\frac12,\frac14\right)$ において共通の接線をもち，さらに $x$ 軸と $x>0$ の部分で接している．
\begin{enumerate}
  \item 円 $C$ の中心Bの座標と半径を求めよ．
  \item 円 $C$，放物線 $P$ と $x$ 軸とで囲まれて，円 $C$ の外部にある部分の面積 $S$ を求めよ．
\end{enumerate}

$xy$ 平面において，曲線 $C:y=|x^2-x-2|$ と，点 $\mathrm A(-1,0)$ を通る傾き $m$ の直線 $l$ が，A以外の異なる2点で交わっている．
\begin{enumerate}
  \item $m$ の値の範囲を求めよ．
  \item $C$ と $l$ で囲まれる2つの部分の面積の和 $S$ を $m$ の式で表し，$S$ が最小となる $m$ の値と最小値を求めよ．
\end{enumerate}

$xy$ 平面上の曲線 $C:y=x^3+ax^2+bx+c$ 上の点Pにおける接線 $l$ が，Pと異なる点Qで $C$ と交わるとする．
\begin{enumerate}
  \item Qにおける接線を $m$ とする．$l$ と $C$ で囲まれた部分の面積と，$m$ と $C$ で囲まれた部分の面積の比を求めよ．
  \item 弧PQ上で接線が $l$ に平行となる点をXとする．$l$ と $C$ で囲まれた部分の面積 $S$ と，三角形PQXの面積 $T$ の比 $S:T$ は一定であることを示し，その値を求めよ．
\end{enumerate}

$x\geqq0$ において $f(x)=\displaystyle\int_0^x|t^2-4t+3|\,dt$ とする．
\begin{enumerate}
  \item $f(x)$ を $x$ の式で表せ．
  \item $f(x)=4$ をみたす $x$ を求めよ．
  \item $a\geqq0$ に対して $g(a)=\displaystyle\int_a^{a+2}|t^2-4t+3|\,dt$ とする．$g(a)$ の最小値と，そのときの $a$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)$ が $f(x)=x^2-2x\displaystyle\int_0^1|f(t)|\,dt$ をみたしているとき，$f(x)$ を求めよ．
  \item 次の関係式をみたす定数 $a$ および1次以下の関数 $g(x)$ の組をすべて求めよ．
  \[\int_a^x\{g(t)-t\,g(a)\}\,dt=x^2+x-6\]
\end{enumerate}

$k$ を実数とする．3次関数 $y=x^3+kx$ のグラフを $C$ とし，連立不等式 $x>1$，$-x<y<0$ の表す領域を $A$ とする．
\begin{enumerate}
  \item 点 $(p,q)$ から $C$ に3本の接線が引けるための条件を，$p,q,k$ の不等式で表せ．
  \item $A$ のどの点からも $C$ に接線が3本引けるような $k$ をすべて求めよ．
\end{enumerate}

実数 $a$ が $0<a<1$ の範囲を動くとき，曲線 $y=x^3-3ax+a$ の極大点と極小点の間にある部分（極大点，極小点は含まない）が通過する範囲を $G$ とする．
\begin{enumerate}
  \item $G$ を求め，図示せよ．
  \item $G$ の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$，$y$ を実数とし，$t$ の関数 $g(t)=xt^2+yt$ の $0\leqq t\leqq1$ における最大値と最小値の差を $W(x,y)$ とする．$W(x,y)$ を $y$ の範囲で場合分けして求めよ．
  \item 次の条件をみたす点 $(x,y)$ 全体の領域 $S$ を求め，図示せよ．
  \begin{center}
  $x>0$ かつ，実数 $z$ で，$0\leqq t\leqq1$ のすべての $t$ に対して $-1\leqq xt^2+yt+z\leqq1$ をみたすものが存在する．
  \end{center}
  \item 次の条件をみたす点 $(x,y,z)$ 全体からなる立体 $V$ の体積を求めよ．
  \begin{center}
  $0\leqq x\leqq1$ かつ，$0\leqq t\leqq1$ のすべての $t$ に対して $-1\leqq xt^2+yt+z\leqq1$．
  \end{center}
\end{enumerate}

実数 $x,y$ が $x^3+y^3=3xy$ を満たしながら動く．
\begin{enumerate}
  \item $(x+1)(y+1)$ のとりうる値の範囲を求めよ．
  \item 実数 $c$ に対し，$x^3+y^3=3xy$ かつ $(x+1)(y+1)=c$ を満たす実数の組 $(x,y)$ の個数を求めよ．
\end{enumerate}

$a,b$ を実数とし，$-1\leqq x\leqq1$ における $|x^3-ax-b|$ の最大値を $M(a,b)$ とする．
\begin{enumerate}
  \item $b=0$ のとき，$M(a,0)$ を $a$ の式で表し，$M(a,0)$ を最小にする $a$ の値を求めよ．
  \item すべての実数 $a,b$ に対して $M(a,b)\geqq\dfrac14$ であることを示し，等号が成り立つ $(a,b)$ をすべて求めよ．
\end{enumerate}

$a,b,c$ を実数とする．$f(x)=x^3+3ax^2+3bx$ とし，$y=f(x)$ と $y=c$ のグラフが相異なる3つの交点をもつとする．交点の $x$ 座標を $\alpha<\beta<\gamma$ とし，$d=a^2-b$ とおく．
\begin{enumerate}
  \item $d>0$ であることを示せ．
  \item $|\beta+a|<\sqrt d$ であることを示せ．また，$\alpha,\beta,\gamma$ はすべて開区間 $\left(-a-2\sqrt d,\ -a+2\sqrt d\right)$ に含まれることを示せ．
  \item $3\sqrt d<\gamma-\alpha\leqq2\sqrt{3d}$ が成り立つことを示し，等号が成り立つときの $c$ を $a,b$ で表せ．
\end{enumerate}

$p$ を正の定数とし，曲線 $C:y=x^3-px$ を考える．座標平面上の点 $(a,b)$ で，次の条件をみたすものを考える．
\begin{center}
条件：点 $(a,b)$ から $C$ に接線がちょうど2本だけ引け，その2本の接線が直交する．
\end{center}
\begin{enumerate}
  \item 条件をみたす点 $(a,b)$ の個数を，$p$ の値によって分類して答えよ．
  \item $p=\dfrac43$ のとき，条件をみたす点 $(a,b)$ をすべて求めよ．
\end{enumerate}

$a$ を実数とし，$f(x)=x^4+ax^3+x^2$ とする．
\begin{enumerate}
  \item 曲線 $y=f(x)$ と異なる2点で接する直線が存在するような $a$ の値の範囲を求めよ．
  \item $a$ が (1) の範囲にあるとき，そのような直線はただ1つであることを示し，曲線 $y=f(x)$ とその直線で囲まれた領域の面積 $S(a)$ を求めよ．
  \item $S(a)=\dfrac{16}{15}$ となる $a$ の値と，そのときの直線の方程式を求めよ．
\end{enumerate}

$0\leqq k\leqq1$ をみたす実数 $k$ に対して，$xy$ 平面上に次の連立不等式で表される3つの領域 $D$，$E$，$F$ を考える．
\begin{center}
\begin{tabular}{l}
$D$ は連立不等式 $y\geqq x^2$，$y\leqq kx$ で表される領域\\
$E$ は連立不等式 $y\leqq x^2$，$y\geqq kx$ で表される領域\\
$F$ は連立不等式 $y\leqq-2x^2+3x$，$y\geqq kx$ で表される領域
\end{tabular}
\end{center}
\begin{enumerate}
  \item 領域 $D\cup(E\cap F)$ の面積 $m(k)$ を求めよ．
  \item $m(k)$ を最小にする $k$ の値と，その最小値を求めよ．
\end{enumerate}

関数 $f(x)=x^2+3x$ について，次の問いに答えよ．
\begin{enumerate}
  \item $x$ が $1$ から $3$ まで変化するときの平均変化率を求めよ．
  \item 微分係数 $f'(1)$ を，定義 $f'(1)=\displaystyle\lim_{h\to0}\dfrac{f(1+h)-f(1)}{h}$ に従って求めよ．
\end{enumerate}

次の関数を微分せよ．
\begin{enumerate}
  \item $y=(x+2)(x^2-3)$
  \item $y=(2x-1)^2$
\end{enumerate}

次の曲線上の点における接線の方程式を求めよ．
\begin{enumerate}
  \item $y=x^3-2x$，点 $(1,-1)$
  \item $y=x^2-4x+5$，点 $(3,2)$
\end{enumerate}

\begin{enumerate}
  \item 不定積分 $\displaystyle\int(3x^2-4x+1)\,dx$ を求めよ．
  \item $f'(x)=6x-2$，$f(0)=1$ を満たす関数 $f(x)$ を求めよ．
\end{enumerate}

次の定積分を求めよ．
\begin{enumerate}
  \item $\displaystyle\int_{-1}^{2}(x^2+x)\,dx$
  \item $\displaystyle\int_{1}^{3}(x-1)(x-3)\,dx$
\end{enumerate}

次の定積分を求めよ．
\begin{enumerate}
  \item $\displaystyle\int_0^3|x-1|\,dx$
  \item $\displaystyle\int_0^2|x^2-1|\,dx$
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)=x^3+ax^2+3x$ がつねに増加するような定数 $a$ の値の範囲を求めよ．
  \item 関数 $g(x)=x^3-3ax^2+3(a+2)x$ が極値をもつような定数 $a$ の値の範囲を求めよ．
\end{enumerate}

$p>0$ とする．関数 $f(x)=x^3-3px+1$ について，次の問いに答えよ．
\begin{enumerate}
  \item 極大値と極小値の差を $p$ で表せ．
  \item 極大値と極小値の差が $32$ となるような $p$ の値を求め，そのときの極小値を求めよ．
\end{enumerate}

放物線 $C:y=x^2$ 上の点 $\mathrm{A}(1,1)$ における法線を $\ell$ とする．
\begin{enumerate}
  \item $\ell$ の方程式を求めよ．
  \item $\ell$ と $C$ の $\mathrm{A}$ 以外の交点の座標を求めよ．
  \item $\ell$ と $C$ で囲まれた部分の面積を求めよ．
\end{enumerate}

1辺の長さが $12$ の正方形の厚紙の四隅から，1辺の長さ $x$ の正方形を切り取り，残りを折り曲げてふたのない直方体の箱を作る．
\begin{enumerate}
  \item 箱の容積 $V$ を $x$ の式で表し，$x$ のとりうる値の範囲を答えよ．
  \item $V$ の最大値と，そのときの $x$ の値を求めよ．
\end{enumerate}

半径 $3$ の球に内接する円柱を考える．円柱の高さを $h$ とする．
\begin{enumerate}
  \item 円柱の体積 $V$ を $h$ の式で表せ．
  \item $V$ の最大値と，そのときの $h$ を求めよ．
\end{enumerate}

曲線 $C:y=x^3-3x$ について，次の問いに答えよ．
\begin{enumerate}
  \item $C$ 上の点 $(1,-2)$ における接線 $\ell$ の方程式と，$\ell$ と $C$ の接点以外の共有点の $x$ 座標を求めよ．
  \item $C$ と $\ell$ で囲まれた部分の面積を求めよ．
\end{enumerate}

放物線 $y=x^2-2x$ と $x$ 軸で囲まれた部分を $D$ とする．
\begin{enumerate}
  \item $D$ の面積を求めよ．
  \item 原点を通る直線 $y=mx$ が $D$ の面積を2等分するとき，$m$ の値を求めよ．
\end{enumerate}

$0\leqq a\leqq 1$ とし，$F(a)=\displaystyle\int_0^1|x-a|\,dx$ とおく．
\begin{enumerate}
  \item $F(a)$ を $a$ の式で表せ．
  \item $F(a)$ の最小値と，そのときの $a$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 整式 $f(x)$ を $(x-a)^2$ で割った余りを $px+q$ とするとき，$f(a)=pa+q$，$f'(a)=p$ が成り立つことを用いて，$x^{10}$ を $(x-1)^2$ で割った余りを求めよ．
  \item 整式 $x^{n}$（$n\geqq2$）を $(x-1)^2$ で割った余りを $n$ の式で表せ．
\end{enumerate}

$a,b,c$ を実数とし，$f(x)=ax^2+bx+c$ とする．$-1\leqq x\leqq1$ を満たすすべての $x$ に対し $|f(x)|\leqq1$ が成り立つとする．
\begin{enumerate}
  \item 積分 $\displaystyle I=\int_{-1}^1\{f'(x)\}^2\,dx$ の最大値を求めよ．また，最大値をとるときの $f(x)$ をすべて求めよ．
  \item 積分 $\displaystyle J=\int_{-1}^1|f'(x)|\,dx$ の最大値を求めよ．また，最大値をとるときの $f(x)$ をすべて求めよ．
\end{enumerate}

$a$ を実数とする．曲線 $C:y=x^3-x$ と放物線 $D:y=x^2+a$ の両方に接する直線の本数を $N(a)$ とする．
\begin{enumerate}
  \item $N(a)$ を $a$ の値によって分類して求めよ．
  \item $N(a)=4$ のとき，4本の直線の傾きの和は $a$ によらない一定の値であることを示し，その値を求めよ．
\end{enumerate}

$a$ が $0<a\leqq1$ の範囲を動くとき，放物線 $C_a:\ y=ax^2-\dfrac{a^3}3$ が通過する領域を $E$ とする．
\begin{enumerate}
  \item $E$ を不等式で表せ（境界を含むかどうかも明らかにせよ）．
  \item $E$ のうち $-1\leqq x\leqq1$ の部分の面積を求めよ．
\end{enumerate}

座標平面上の2点 P，Q が曲線 $y=x^3$ $(-1\leqq x\leqq1)$ 上を自由に動くとき，線分 PQ を $1:2$ に内分する点 R が動く範囲を $D$ とする．ただし P$=$Q のときは R$=$P とする．
\begin{enumerate}
  \item $a$ を $-1\leqq a\leqq1$ をみたす実数とするとき，点 $(a,b)$ が $D$ に属するための $b$ の条件を $a$ を用いて表せ．
  \item $D$ の面積を求めよ．
\end{enumerate}

$a>0$，$b$ を実数とし，$f(x)=x^3-3a^2x$ とおく．方程式 $f(x)=b$ が相異なる3つの実数解をもつような点 $(a,b)$ に対し，その3つの解のうち開区間 $-1<x<1$ に含まれるものの個数を $N(a,b)$ とする．
\begin{enumerate}
  \item $N(a,b)=3$ となる点 $(a,b)$ の範囲を求めて図示し，その面積を求めよ．
  \item $N(a,b)=2$ となる点 $(a,b)$ の範囲を求めて図示し，その面積を求めよ．
\end{enumerate}

$S$ は $0<S\leqq\dfrac12$ をみたす定数とする．一辺の長さが1の正方形 ABCD を考える．3点 P，Q，R はそれぞれ辺 AB，AD，CD 上にあり，3点 A，P，Q および3点 P，Q，R はどちらも面積が $S$ の三角形の3頂点であるとする．$\mathrm{AP}=p$ とおく．
\begin{enumerate}
  \item AQ，DR を $p$，$S$ で表し，$p$ のとりうる値の範囲を求めよ．
  \item $\dfrac{\mathrm{DR}}{\mathrm{AQ}}$ の最大値 $M(S)$ を求めよ．
  \item $\dfrac{\mathrm{DR}}{\mathrm{AQ}}$ の最小値 $m(S)$ を求めよ．
\end{enumerate}

$a,\ b$ を実数とする．座標平面上の曲線 $C:\ y=ax^3+bx$ と，原点を中心とする半径1の円 $K$ を考える．
\begin{enumerate}
  \item $C$ と $K$ の共有点の個数が6個であるための $a,\ b$ の必要十分条件を，$a,\ b$ の不等式で表せ．
  \item $C$ と $K$ の共有点の個数が6個となるような実数 $b$ が存在する $a$ の値の範囲を求めよ．
\end{enumerate}

座標平面上の放物線 $C:\ y=x^2$ を考える．$C$ 上の点 Q に対し，Q を通り Q における $C$ の接線に垂直な直線を，Q における $C$ の法線という．
\begin{enumerate}
  \item 点 $\mathrm P(p,q)$ に対し，「Q における $C$ の法線が P を通るような $C$ 上の点 Q がちょうど3個ある」ための $p,\,q$ の条件を求めよ．
  \item $r>0$ とし，不等式 $x^2+(y-4)^2<r^2$ が表す領域を $D$ とする．$D$ 内のすべての点 P が (1) の条件を満たすような $r$ の最大値を求めよ．
\end{enumerate}

座標平面上の曲線 $C:\ y=x^3-x$ を考える．直線 $\ell$ が $C$ と相異なる3点で交わるとき，3交点を $x$ 座標の小さい順に Q，R，S とする．次の条件を (＊) とよぶ．
\begin{center}
(＊)\quad 直線 $\ell$ は $C$ と相異なる3点で交わり，$\mathrm{QR}=2\,\mathrm{RS}$ が成り立つ．
\end{center}
\begin{enumerate}
  \item 直線 $\ell$ が (＊) を満たすとき，R の $x$ 座標 $t$ は正であることを示し，$\ell$ の方程式を $t$ で表せ．
  \item 点 P を通り (＊) を満たす直線 $\ell$ が存在するような点 P のとりうる範囲を求め，座標平面上に図示せよ．
\end{enumerate}

$k$ を実数とし，座標平面上の曲線 $C$ を $y=x^3-kx$ で定める．$C$ 上の2点 P，Q に対する次の条件 $(*)$ を考える．
\begin{center}
\begin{minipage}{0.86\linewidth}
条件 $(*)$：原点 O，点 P，点 Q は相異なり，$C$ の O，P，Q における3本の接線のどの2本も交わり，3本の接線で囲まれる三角形は直角二等辺三角形である．
\end{minipage}
\end{center}
\begin{enumerate}
  \item 条件 $(*)$ をみたす P，Q が存在するような $k$ の範囲を求めよ．
  \item $k$ が (1) の範囲にあるとき，条件 $(*)$ をみたす2点の組 $\{\mathrm P,\mathrm Q\}$ の個数を求めよ．
  \item $k=3$ とする．P，Q が条件 $(*)$ をみたすように動くとき，3本の接線で囲まれる三角形の面積 $S$ の最大値 $M$ と最小値 $m$ を求めよ．
\end{enumerate}

座標平面上の放物線 $C:y=x^2$ を考える．$C$ 上の原点以外の点 $\mathrm X$ に対し，$\mathrm X$ における $C$ の接線と直交し $\mathrm X$ を通る直線（$\mathrm X$ における法線）と $C$ の交点のうち $\mathrm X$ と異なる点を $\mathrm X^*$ と書く．

$a$ を正の実数とし，$\mathrm P_0=(a,\,a^2)$，$\mathrm P_{k+1}=\mathrm P_k{}^*$（$k=0,1,2,\dots$）により $C$ 上の点 $\mathrm P_0,\mathrm P_1,\mathrm P_2,\dots$ を定める（どの $\mathrm P_k$ も原点と異なり，この定義は意味をもつ）．また，線分 $\mathrm P_k\mathrm P_{k+1}$ と $C$ で囲まれる部分の面積を $S_k$ とする．
\begin{enumerate}
  \item $a$ がすべての正の実数を動くとき，$\dfrac{S_1}{S_0}$ のとりうる値の範囲を求めよ．
  \item $a=\dfrac12$ とする．$\mathrm P_{100}$ の $x$ 座標の整数部分を求めよ．
\end{enumerate}

0でない実数 $a$，$b$，$c$ が次の条件 (i)，(ii) をみたしながら動く．
\begin{enumerate}[label=(\roman*)]
  \item $|a|\leqq1$，$|c|\leqq1$，$b\leqq-1$
  \item 2つの放物線 $C_1:y=ax^2$ と $C_2:y=b(x-1)^2+c$ は接している．
\end{enumerate}
ただし，2つの曲線が接するとは，ある共有点において共通の接線をもつことであり，その共有点を接点という．
\begin{enumerate}
  \item $C_1$ と $C_2$ が接するとき，接点はただ1つであることを示し，接点を $(X,Y)$ として $a$，$b$，$c$ を $X$，$Y$ で表せ．
  \item $C_1$ と $C_2$ の接点が動く範囲を図示し，その面積を求めよ．
\end{enumerate}

関数 $y=f(x)$ のグラフ $C$ は，座標平面で原点に関して点対称である．さらに $C$ の $x\leqq0$ の部分は，軸が $y$ 軸に平行で，点 $\left(-\dfrac12,\dfrac14\right)$ を頂点とし，原点を通る放物線と一致している．

$C$ 上の点 $P_0(1,f(1))$ から始めて，$n=0,1,2,\dots$ に対し，$C$ 上の点 $P_{n+1}$ を「$P_n$ と異なり，$P_{n+1}$ における $C$ の接線が $P_n$ を通る点」として定める．
\begin{enumerate}
  \item すべての $n$ について $P_{n+1}$ はただ1つに定まることを示し，$P_n$ の $x$ 座標 $x_n$ を求めよ．
  \item $n\geqq1$ に対し，$P_n$ における $C$ の接線と $C$ によって囲まれる図形の面積を $S_n$ とする．$\displaystyle\sum_{n=1}^{\infty}S_n$ を求めよ．
\end{enumerate}

$k$ を正の定数とする．放物線 $y=x^2$ 上の2点 P，Q が，直線 PQ が原点 O を通らないようにして，次の条件をみたしながら動く．
\begin{center}
放物線と線分 PQ で囲まれる部分の面積が，三角形 OPQ の面積の $k$ 倍である．
\end{center}
線分 PQ の中点 R が描く図形を，$k$ の値によって場合分けして求めよ．

solutions.tex:
P$(p,p^2)$，Q$(q,q^2)$（$p<q$）とし，$d=q-p>0$，$s=\frac{p+q}2$ とおく．R$=\left(s,\frac{p^2+q^2}2\right)=\left(s,\ s^2+\frac{d^2}4\right)$，$pq=s^2-\frac{d^2}4$．

直線 PQ は $y=(p+q)x-pq$ で，弓形の面積は
\[\int_p^q\{(p+q)x-pq-x^2\}\,dx=\int_p^q(x-p)(q-x)\,dx=\frac{d^3}6 .\]
三角形 OPQ の面積は $\frac12|pq^2-qp^2|=\frac12|pq|\,d$．直線 PQ が O を通らないことは $pq\neq0$ と同値．条件は
\[\frac{d^3}6=\frac k2|pq|\,d\iff|pq|=\frac{d^2}{3k}\quad(pq\neq0).\]

\textbf{(ア) $pq>0$ のとき．}$s^2-\frac{d^2}4=\frac{d^2}{3k}$，すなわち $s^2=\frac{(3k+4)d^2}{12k}$．$d>0$ より $s\neq0$ で，$\frac{d^2}4=\frac{3k}{3k+4}s^2$．よって R の $y$ 座標は $s^2+\frac{3k}{3k+4}s^2=\frac{6k+4}{3k+4}s^2$．逆に任意の $s\neq0$ に対し $d=\sqrt{\frac{12k}{3k+4}}|s|>0$ とおけば $pq=\frac{d^2}{3k}>0$ となり条件をみたす．よって R は放物線 $y=\frac{6k+4}{3k+4}x^2$ の $x\neq0$ の部分全体を動く．

\textbf{(イ) $pq<0$ のとき．}$\frac{d^2}4-s^2=\frac{d^2}{3k}$，すなわち $s^2=\frac{(3k-4)d^2}{12k}$．
\begin{itemize}
  \item $0<k<\frac43$：右辺は負で不可能．
  \item $k=\frac43$：$s=0$ で，$d>0$ は任意．このとき $pq=-\frac{d^2}4<0$ で条件をみたし，R$=\left(0,\frac{d^2}4\right)$ は半直線 $x=0$，$y>0$ 全体を動く．
  \item $k>\frac43$：$s\neq0$ で $\frac{d^2}4=\frac{3k}{3k-4}s^2$，R の $y$ 座標は $\frac{6k-4}{3k-4}s^2$．逆に任意の $s\neq0$ に対し $d=\sqrt{\frac{12k}{3k-4}}|s|$ とおけば $pq=s^2-\frac{d^2}4=-\frac{d^2}{3k}<0$ で条件をみたす．よって R は放物線 $y=\frac{6k-4}{3k-4}x^2$ の $x\neq0$ の部分全体を動く．
\end{itemize}

以上より，R の描く図形は
\begin{itemize}
  \item $0<k<\frac43$ のとき：\textbf{放物線 $\boldsymbol{y=\dfrac{6k+4}{3k+4}x^2}$（$x\neq0$）}
  \item $k=\frac43$ のとき：\textbf{放物線 $\boldsymbol{y=\dfrac32x^2}$（$x\neq0$）と半直線 $\boldsymbol{x=0,\ y>0}$}
  \item $k>\frac43$ のとき：\textbf{2つの放物線 $\boldsymbol{y=\dfrac{6k+4}{3k+4}x^2}$，$\boldsymbol{y=\dfrac{6k-4}{3k-4}x^2}$（いずれも $x\neq0$）}
\end{itemize}
（$k=\frac43$ の半直線は，O における接線が PQ に平行なときの「弓形の面積は三角形の $\frac43$ 倍」に対応する．）\hfill$\square$

statement.tex:
$k>1$ とし，2つの放物線 $y=x^2+1$ と $y=kx^2$ で囲まれた部分を $D_k$ とする．$a\geqq0$ とし，放物線 $y=x^2+1$ 上の点 P$(a,\,a^2+1)$ における接線を $L$ とする．「$L$ が $D_k$ の面積を2等分する」とは，$D_k$ のうち $L$ の上側にある部分の面積と下側にある部分の面積が等しいことをいう．
\begin{enumerate}
  \item $c=\sqrt[3]{\dfrac{k}{4(k-1)}}$ とおく．$L$ が $D_k$ の面積を2等分するための必要十分条件は $a^2=4c^3(1-c)$ であることを示せ．
  \item $a$ を固定する．$L$ が $D_k$ の面積を2等分するような $k\ (>1)$ の個数 $N(a)$ を求めよ．
\end{enumerate}

実数 $a,b$ について，次の条件を考える．
\begin{center}
「すべての実数 $x$ に対して $|2x^2+ax+b|\geqq|x^2-2|$ が成り立つ．」
\end{center}
\begin{enumerate}
  \item この条件をみたす点 $(a,b)$ の集合を $ab$ 平面上に図示せよ．
  \item (1) の集合のうち $b\leqq8$ をみたす部分の面積を求めよ．
\end{enumerate}

$f(x)=x^3-3x$ とし，曲線 $y=f(x)$ を $C$ とする．点 $\mathrm P(a,b)$ から $C$ にちょうど3本の接線が引けるとき，3つの接点を $\mathrm A(\alpha,f(\alpha))$，$\mathrm B(\beta,f(\beta))$，$\mathrm C(\gamma,f(\gamma))$ とし，$\triangle\mathrm{ABC}$ の重心を G，面積を $S$ とする．
\begin{enumerate}
  \item P から $C$ にちょうど3本の接線が引けるための $a,b$ の条件を求めよ．
  \item G の $y$ 座標から $f\!\left(\text{G の $x$ 座標}\right)$ を引いた値を $D$ とする．$D$ を $a,b$ で表し，G は $C$ 上にないことを示せ．また，$a>0$ を固定して $b$ を動かすとき，$D$ のとりうる値の範囲を求めよ．
  \item $a>0$ を固定して $b$ を動かすとき，$S$ の最大値と，そのときの $b$ を求めよ．
\end{enumerate}
